from __future__ import annotations
from typing import Callable, TypeVar
B = TypeVar("B")
def diagonal(model: list[tuple[B, ...]]) -> tuple[B, ...]:
    return tuple(row[i] for i, row in enumerate(model))
def extract_witness(model: list[tuple[B, ...]], g: Callable[[B], B]) -> tuple[int, B] | None:
    d = diagonal(model)
    target = tuple(g(x) for x in d)
    for a, row in enumerate(model):
        if row == target:
            assert g(d[a]) == d[a]
            return a, d[a]
    return None
if __name__ == "__main__":
    print(extract_witness([(7,)], lambda _: 7))

from __future__ import annotations
from itertools import product
from typing import Sequence, TypeVar
B = TypeVar("B")
def all_observers(values: Sequence[B], states: int) -> list[tuple[B, ...]]:
    return list(product(values, repeat=states))
def completeness_report(model: list[tuple[B, ...]], values: Sequence[B]) -> dict[str, object]:
    universe = set(all_observers(values, len(model)))
    represented = set(model)
    return {"complete": represented == universe,
            "represented": len(represented), "total": len(universe),
            "omitted": sorted(universe - represented, key=repr)}
if __name__ == "__main__":
    print(completeness_report([(False,),], [False, True]))

from __future__ import annotations
from typing import Callable, Sequence, TypeVar
B = TypeVar("B"); X = TypeVar("X")
def compose_probe(observer: Sequence[B], h: Callable[[B], X]) -> tuple[X, ...]:
    return tuple(h(value) for value in observer)
def distinguish(f: Sequence[B], g: Sequence[B]) -> int | None:
    return next((i for i, (x, y) in enumerate(zip(f, g)) if x != y), None)
if __name__ == "__main__":
    observer = (2, 0, 3, 1)
    print("identity recovery:", compose_probe(observer, lambda x: x))
    print("parity behavior:", compose_probe(observer, lambda x: x % 2))

